use std::env;

pub fn parse_count() -> i32 {
    let args: Vec<String> = env::args().collect();
    let mut count = 5_i32;

    if args.len() > 1 && args[1] == "--a" {
        count = parse_stoi_like(&args[2]);
    }

    count
}

fn parse_stoi_like(input: &str) -> i32 {
    let trimmed = input.trim_start();
    let bytes = trimmed.as_bytes();

    let mut index = 0usize;
    let mut sign = 1_i64;
    if let Some(first) = bytes.first() {
        if *first == b'+' {
            index = 1;
        } else if *first == b'-' {
            sign = -1;
            index = 1;
        }
    }

    let start_digits = index;
    let mut value = 0_i64;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = (value * 10) + i64::from(bytes[index] - b'0');
        index += 1;
    }

    if index == start_digits {
        panic!("invalid stoi argument");
    }

    let signed = value * sign;
    if signed < i64::from(i32::MIN) || signed > i64::from(i32::MAX) {
        panic!("stoi out of range");
    }

    signed as i32
}

#[cfg(test)]
mod tests {
    use super::parse_stoi_like;

    #[test]
    fn parses_prefix_like_stoi() {
        assert_eq!(parse_stoi_like("42xyz"), 42);
        assert_eq!(parse_stoi_like("   -7"), -7);
        assert_eq!(parse_stoi_like("+11"), 11);
    }
}

