use crate::cli::parse_count;
use crate::hopscotch_map::HopscotchMap;

pub fn compute_result(count: i32) -> (usize, i32) {
    let mut map = HopscotchMap::<i32, i32>::new();

    let mut i = 0_i32;
    while i < count {
        map.insert((i, i.wrapping_mul(2)));
        i += 1;
    }

    let mut removed = 0_i32;
    let mut i = 0_i32;
    while i < count {
        removed += map.erase(i) as i32;
        i += 2;
    }

    (map.size(), removed)
}

pub fn run() {
    let count = parse_count();
    let (size, removed) = compute_result(count);
    println!("{size} {removed}");
}

#[cfg(test)]
mod tests {
    use super::compute_result;

    #[test]
    fn matches_examples() {
        assert_eq!(compute_result(5), (2, 3));
        assert_eq!(compute_result(0), (0, 0));
        assert_eq!(compute_result(1), (0, 1));
        assert_eq!(compute_result(2), (1, 1));
        assert_eq!(compute_result(3), (1, 2));
    }
}

