use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.inner.insert(entry.0, entry.1)
    }

    pub fn erase(&mut self, key: K) -> usize {
        usize::from(self.inner.remove(&key).is_some())
    }

    pub fn size(&self) -> usize {
        self.inner.len()
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

